window.dameMesCorto = function( strMes ) {
    aMes = new Array( "ape", "ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic", "cie" );
    return aMes[ strMes ];
}

window.CheckmarkFormatter = function(value) {
    return ( value == "C" || value == "H" ) ? "<img src=\'css/images/pin.png\'>" :  value;
}

window.MCFormatter = function(value) {
    if ( value.substring( 1 ) == "A" ) {
        return value.substring( 0, 1 );
    } else {
        return "<span title=\"La póliza corresponde a la cancelación de un compromiso que fué autorizado en diferente mes\">" + value.substring( 0, 1 ) + "<span style=\"color:red\">" + value.substring( 1 ) + "</span></span>";
    }
}

window.PolFormatter = function(value, apg) {
    if (apg != "ORD" ) {
        return value;
    } else {
        return value + "<img src=\'css/images/punto.png\'>";
    }
}

window.FormatoDia = function(value, mes) {
    if ( mes != $("#mesActual").attr( "ma" ) ) {
        return value + "-<font color=\"red\">" + dameMesCorto(dataLibroDiariomes) + "</font>";
    } else {
        return value;
    }
}

window.ldFormatearTexto = function (value, e) {
    return ( e == "C" || e == "H"  ) ? "<del><i>" + value + "</i></del>" : "<span title=\"" + value + "\">" + value + "</span>";
}

window.LDFormatoMoneda = function(value, h) {
    // Si la suma de DEBE y HABER no son iguales, toda la línea se mostrará en color rojo
    strIni = ""
    strFin = ""
    if (value != h ) {
        strIni = "<span class=\"parpadea\" title=\"Hay diferencia entre la suma del Debe y del Haber\"><font color=#FF0000><b>";
        strFin = "</b></font></span>";
    }

    if (value === null || value === "" || !(value != 0)) {
        return "";
    } else {
        var n = value,
        c = 2,
        d = ".",
        t = ","
        s = n < 0 ? "-" : "",
        i = parseInt(n = Math.abs(+n || 0).toFixed(2)) + "",
        j = (j = i.length) > 3 ? j % 3 : 0;
        return strIni + s + (j ? i.substr(0, j) + t : "") + i.substr(j).replace(/(\d{3})(?=\d)/g, "$1" + t) + (c ? d + Math.abs(n - i).toFixed(c).slice(2) : "") + strFin;
    }
} 

window.filtrarLibroDiario = function() {
    if ($("#buscar").val().length > 4 || $("#buscar").val() == "") {
        $("#tbl-libro-diario").tabla('filtrarFilas', $("#buscar").val())
    }
}

window.chkMscId = function( msc_id ) {
    const edomes = $("#mesActual").attr("edomes");
    if ( edomes && edomes === 'A') {
        $("#cancelar").attr("style", "visibility: visible");
        $("#adicionar").attr("style", "visibility: visible");
        $("#modificar").attr("style", "visibility: visible");
        $("#recalc").attr("style", "visibility: visible");
    } else {
        $("#cancelar").attr("style", "display:none");
        $("#adicionar").attr("style", "display:none");
        $("#modificar").attr("style", "display:none");
        $("#recalc").attr("style", "display:none");
    }
}

$("#mostrar1, #mostrar2, #mostrar3").on("click", function(){
    $("#tbl-libro-diario").tabla("llenaTabla");
    chkMscId( $("#mesActual").attr("ma") );
});